USE master;

DECLARE
	/* Set these */
	@DbName NVARCHAR(100) = 'Elector8_$E8DbName$',
	@Filename NVARCHAR(100) = 'C:\_ Databases\$Folder$\$FileName$.bak',
	@FilenamePI NVARCHAR(100) = 'C:\_ Databases\$Folder$\$PIFilename$.bak',
	
	/* Check these */
	@LogicalName NVARCHAR(100) = 'SELECTDB_Data',
	@LogicalNameLog NVARCHAR(100) = 'SELECTDB_Log',
	@LogicalNamePI NVARCHAR(100) = 'Elector8PrivateInfo',
	@LogicalNameLogPI NVARCHAR(100) = 'Elector8PrivateInfo_log',
	@SQLFilesNames NVARCHAR(100) = NULL,
	@SQLFileDir NVARCHAR(500) = 'C:\Program Files\Microsoft SQL Server\MSSQL15.MSSQLSERVER\MSSQL\DATA\',
	@DataFile NVARCHAR(700), @LogFile NVARCHAR(700), @DataFilePI NVARCHAR(700), @LogFilePI NVARCHAR(700), @SQL NVARCHAR(MAX);

IF @SQLFilesNames IS NULL SET @SQLFilesNames = @DbName;
SET @DataFile = @SQLFileDir + @SQLFilesNames + '.mdf';
SET @LogFile = @SQLFileDir + @SQLFilesNames + '.ldf';
SET @DataFilePI = @SQLFileDir + @SQLFilesNames + 'PrivateInfo.mdf';
SET @LogFilePI = @SQLFileDir + @SQLFilesNames + 'PrivateInfo.ldf';

PRINT @DataFile + ', ' + @LogFile;



/* RUN FIRST to get current file LogicalNames */
RESTORE FILELISTONLY
FROM DISK = @Filename;
RESTORE FILELISTONLY
FROM DISK = @FilenamePI;



/* CREATE DBs */
SET @SQL = 
N'IF EXISTS (SELECT * FROM sys.databases AS D WHERE D.name = ''' + @DbName + ''') ALTER DATABASE [' + @DbName + '] SET SINGLE_USER WITH ROLLBACK IMMEDIATE
  IF EXISTS (SELECT * FROM sys.databases AS D WHERE D.name = ''' + @DbName + 'PrivateInfo'') ALTER DATABASE [' + @DbName + 'PrivateInfo] SET SINGLE_USER WITH ROLLBACK IMMEDIATE';
EXEC sp_executesql @stmt = @SQL;

SET @SQL = 
N'IF EXISTS (SELECT * FROM sys.databases AS D WHERE D.name = ''' + @DbName + ''') ALTER DATABASE [' + @DbName + '] SET MULTI_USER
  IF EXISTS (SELECT * FROM sys.databases AS D WHERE D.name = ''' + @DbName + 'PrivateInfo'') ALTER DATABASE [' + @DbName + 'PrivateInfo] SET MULTI_USER';
EXEC sp_executesql @stmt = @SQL;

SET @SQL = 
N'DROP DATABASE IF EXISTS ' + @DbName + ';
  DROP DATABASE IF EXISTS ' + @DbName + 'PrivateInfo';
EXEC sp_executesql @stmt = @SQL;

SET @SQL = 
N'CREATE DATABASE '+ @DbName + ';
  CREATE DATABASE '+ @DbName + 'PrivateInfo';
EXEC sp_executesql @stmt = @SQL;

SET @SQL = 
N'RESTORE DATABASE [' + @DbName + ']
FROM DISK = ''' + @Filename + '''
WITH
    MOVE ''' + @LogicalName + '''
    TO ''' + @DataFile + ''',
    MOVE ''' + @LogicalNameLog + '''
    TO ''' + @LogFile + ''',
    REPLACE';
PRINT @SQL;
EXEC sp_executesql @stmt = @SQL;

SET @SQL = 
N'RESTORE DATABASE [' + @DbName + 'PrivateInfo]
FROM DISK = ''' + @FilenamePI + '''
WITH
    MOVE ''' + @LogicalNamePI + '''
    TO ''' + @DataFilePI + ''',
    MOVE ''' + @LogicalNameLogPI + '''
    TO ''' + @LogFilePI + ''',
    REPLACE';
PRINT @SQL;
EXEC sp_executesql @stmt = @SQL;



SET @SQL =
N'USE [' + @DbName + '];

/* Find the current PrivateInfo database referenced */
DECLARE @CurrentPrivateInfo NVARCHAR(200);
SELECT TOP(1)
    @CurrentPrivateInfo = REVERSE(SUBSTRING(
		REVERSE(SM.definition), 
		CHARINDEX(REVERSE(''PrivateInfo''), REVERSE(SM.definition)), 
		CHARINDEX('' '', REVERSE(SM.definition), CHARINDEX(REVERSE(''PrivateInfo''), REVERSE(SM.definition))) - CHARINDEX(REVERSE(''PrivateInfo''), REVERSE(SM.definition)))) 
FROM 
	[' + @DbName + '].sys.views AS V
	INNER JOIN [' + @DbName + '].sys.sql_modules AS SM ON SM.object_id = V.object_id
WHERE SM.definition LIKE ''%PrivateInfo%'';

/* Alter views must be the only statement in a batch and GO statements must be on new lines, therefore it is easier to use a cursor than worry about either SSMS or FOR XML stripping or encoding new lines. */
DECLARE ViewCursor CURSOR LOCAL FAST_FORWARD
FOR
    SELECT 
        REPLACE(REPLACE(SM.definition, ''CREATE VIEW'', ''ALTER VIEW''), @CurrentPrivateInfo, CONCAT(DB_NAME(), ''PrivateInfo''))
    FROM 
        [' + @DbName + '].sys.views AS V
        INNER JOIN [' + @DbName + '].sys.sql_modules AS SM ON SM.object_id = V.object_id
    WHERE SM.definition LIKE ''%'' + @CurrentPrivateInfo + ''%'';

DECLARE @Sql NVARCHAR(MAX);

OPEN ViewCursor;

FETCH NEXT FROM ViewCursor INTO @Sql;
WHILE @@FETCH_STATUS = 0
BEGIN
    EXEC sp_executesql @stmt = @Sql;
    FETCH NEXT FROM ViewCursor INTO @Sql;
END;
CLOSE ViewCursor;
DEALLOCATE ViewCursor;

UPDATE [' + @DbName + '].dbo.Environment
SET Environment.Value = 1
WHERE Environment.Description = ''UseTestServices'' OR Environment.Description = ''Debug'';

SELECT * 
FROM
	(
		SELECT E.OwnerName, E.ERONationID
		FROM [' + @DbName + '].dbo.ERO AS E
	) AS ero
	CROSS JOIN (
		SELECT TOP(1) SL.Version, SL.DateApplied AS [Last Updated]
		FROM [' + @DbName + '].dbo.ScriptLog AS SL
		WHERE SL.Version <> ''0.0.0''
		ORDER BY
		    CONVERT(INT, SUBSTRING(SL.Version, 0, CHARINDEX(''.'', SL.Version))) DESC,
			CONVERT(INT, SUBSTRING(SL.Version, CHARINDEX(''.'', SL.Version) + 1, CHARINDEX(''.'', SL.Version, CHARINDEX(''.'', SL.Version) + 1) - CHARINDEX(''.'', SL.Version) - 1)) DESC,
			CONVERT(DECIMAL(6,3), SUBSTRING(SL.Version, CHARINDEX(''.'', SL.Version, CHARINDEX(''.'', SL.Version) + 1) + 1, 1000)) DESC,
		    SL.DateApplied DESC
	) AS ver
	CROSS JOIN (
		SELECT SUM(F.size) * 8 / 1024.0 / 1024.0 AS [Total Size (GB)]
		FROM
			(
				SELECT DF.size
				FROM [' + @DbName + '].sys.database_files AS DF
				UNION ALL
				SELECT DF.size
				FROM [' + @DbName + 'PrivateInfo].sys.database_files AS DF
			) AS F
	) AS size';
EXEC sp_executesql @stmt = @SQL;
